-- =========================================================
-- player modeling feature dataset
-- one row per player, team, and match
-- =========================================================

with pass_features as (select e.player_id, e.team_id, e.match_id, count(*) as total_passes, sum(case when pa.outcome_id is null then 1 else 0 end) as completed_passes,
sum(case when pa.outcome_id is null and pa.end_location_x - e.location_x >= 10 then 1 else 0 end) as progressive_passes from events as e join passes as pa on e.event_id = pa.event_id group by e.player_id, e.team_id, e.match_id), shot_features as (select e.player_id, e.team_id, e.match_id, count(*) as total_shots, sum(case when s.outcome_id = 97 then 1 else 0 end) as goals, sum(s.statsbomb_xg) as total_xg from events as e join shots as s on e.event_id = s.event_id group by e.player_id, e.team_id, e.match_id),
dribble_features as (select e.player_id, e.team_id, e.match_id, count(*) as total_dribbles, sum(case when d.outcome_id = 8 then 1 else 0 end) as successful_dribbles from events as e join dribbles as d on e.event_id = d.event_id group by e.player_id, e.team_id, e.match_id),
carry_features as (select e.player_id, e.team_id, e.match_id, count(*) as total_carries, sum(case when c.end_location_x - e.location_x >= 10 then 1 else 0 end) as progressive_carries from events as e join carries as c on e.event_id = c.event_id group by e.player_id, e.team_id, e.match_id), duel_features as (select e.player_id, e.team_id, e.match_id, count(*) as total_duels, sum(case when d.outcome_id in (4, 15, 16, 17) then 1 else 0 end) as successful_duels from events as e join duels as d on e.event_id = d.event_id group by e.player_id, e.team_id, e.match_id), appearance_features as (select player_id, count(distinct match_id) as matches_played from events where player_id is not null group by player_id), player_matches as (select distinct player_id, team_id, match_id from events where player_id is not null and team_id is not null), position_counts as (select player_id, position_id, count(*) as position_event_count from events where player_id is not null and position_id is not null group by player_id, position_id), ranked_positions as (select player_id, position_id, position_event_count, row_number() over (partition by player_id order by position_event_count desc) as position_rank from position_counts), primary_positions as (select player_id, position_id as primary_position_id, position_event_count from ranked_positions where position_rank = 1) select p.player_id, p.player_name, pm.team_id, pm.match_id, pp.primary_position_id, pp.position_event_count, case when pp.primary_position_id = 1 then 'Goalkeeper' when pp.primary_position_id between 2 and 8 then 'Defender' when pp.primary_position_id in (9, 10, 11, 12, 13, 14, 15, 16, 18, 19, 20) then 'Midfielder' when pp.primary_position_id in (17, 21, 22, 23, 24, 25) then 'Forward' else 'Unknown' end as role_group, coalesce(pf.total_passes, 0) as total_passes, coalesce(pf.completed_passes, 0) as completed_passes, coalesce(pf.progressive_passes, 0) as progressive_passes, coalesce(round(100.0 * coalesce(pf.completed_passes, 0) / nullif(pf.total_passes, 0), 2), 0) as pass_completion_rate, coalesce(round(100.0 * coalesce(pf.progressive_passes, 0) / nullif(pf.total_passes, 0), 2), 0) as progressive_pass_rate, coalesce(sf.total_shots, 0) as total_shots, coalesce(sf.goals, 0) as goals, round(1.0 * coalesce(sf.total_xg, 0), 2) as total_xg, coalesce(round(1.0 * coalesce(sf.total_xg, 0) / nullif(sf.total_shots, 0), 2), 0) as average_xg_per_shot, round(coalesce(sf.goals, 0) - coalesce(sf.total_xg, 0), 2) as goals_minus_xg, coalesce(df.total_dribbles, 0) as total_dribbles, coalesce(df.successful_dribbles, 0) as successful_dribbles, coalesce(round(100.0 * coalesce(df.successful_dribbles, 0) / nullif(df.total_dribbles, 0), 2), 0) as dribble_success_rate, coalesce(cf.total_carries, 0) as total_carries, coalesce(cf.progressive_carries, 0) as progressive_carries, coalesce(du.total_duels, 0) as total_duels, coalesce(du.successful_duels, 0) as successful_duels, coalesce(round(100.0 * coalesce(du.successful_duels, 0) / nullif(du.total_duels, 0), 2), 0) as duel_success_rate, coalesce(af.matches_played, 0) as matches_played from player_matches as pm join players as p on pm.player_id = p.player_id left join pass_features as pf on pm.player_id = pf.player_id and pm.team_id = pf.team_id and pm.match_id = pf.match_id left join shot_features as sf on pm.player_id = sf.player_id and pm.team_id = sf.team_id and pm.match_id = sf.match_id left join dribble_features as df on pm.player_id = df.player_id and pm.team_id = df.team_id and pm.match_id = df.match_id left join carry_features as cf on pm.player_id = cf.player_id and pm.team_id = cf.team_id and pm.match_id = cf.match_id left join duel_features as du on pm.player_id = du.player_id and pm.team_id = du.team_id and pm.match_id = du.match_id left join appearance_features as af on pm.player_id = af.player_id left join primary_positions as pp on pm.player_id = pp.player_id;
